-- =====================================================================
-- Mapa de Obras SINFRA: instalações públicas iniciais (270 prédios e espaços)
--
-- Rodar depois do schema.sql. Carregado também na demonstração.
-- Gerado em 04/10/2026 a partir de bases públicas oficiais; cada linha diz a
-- fonte na observação. São prédios REAIS com localização aproximada:
-- conferir no mapa e corrigir pela tela "Instalações" antes do uso real.
--
-- Fontes:
--   Escolas e creches municipais: Censo Escolar 2025 (INEP), dependência
--     municipal e em atividade; inclui a ocupação do prédio (próprio,
--     alugado, cedido).
--   Saúde: Cadastro Nacional de Estabelecimentos de Saúde (CNES/Ministério da
--     Saúde), gestão municipal; unidades do mesmo tipo a menos de 40 m foram
--     reunidas num ponto só (a observação lista todas).
--   Assistência social: Censo SUAS 2025 e cadastro de equipamentos do MDS.
--   Secretarias e órgãos: endereços do site da Prefeitura
--     (imperatriz.ma.gov.br), localizados pelo Cadastro Nacional de Endereços
--     para Fins Estatísticos do IBGE (CNEFE, Censo 2022).
--   Praças, esportes, mercados, cemitérios, terminais e parte das
--     localizações de escolas: © colaboradores do OpenStreetMap, dados sob a
--     licença ODbL (openstreetmap.org/copyright).
--
-- Ficaram de fora por falta de localização confiável: 6 escolas
-- (Escola Municipal Domingos Moraes, Escola Municipal de Educação Infantil José Carneiro dos Santos, Escola Municipal de Educação Infantil Frei Benjamin Zanardini, Escola Municipal Pedro Ferreira Alencar, Escola Municipal de Educação Infantil Marlene Soares, Escola Municipal João Batista de Paiva),
-- a Secretaria de Agricultura (Av. Babaçulândia com Rua João Palmeira) e
-- órgãos instalados em prédios de terceiros (Procon no Imperial Shopping,
-- conselhos no Palácio do Comércio). Pátio de máquinas, usina de asfalto e
-- almoxarifado da SINFRA não constam em nenhuma base: cadastrar pela tela.
-- =====================================================================

begin;

-- Carga de referência: não entra na auditoria (ela registra atos de usuários).
select set_config('app.sem_auditoria', 'on', true);

-- Rodar duas vezes duplicaria as instalações (e pela tela ninguém exclui).
do $$
begin
  if exists (select 1 from public.instalacoes where nome = 'Prefeitura Municipal de Imperatriz') then
    raise exception 'As instalações iniciais já foram carregadas.';
  end if;
end;
$$;

